/* -----------------------------------------------------------------------
 * touch_region.c
 * TEAM CODE (owner: Tony - display and user interface) - written by the BJT2 team, not generated by STM32CubeMX.
 * Authors: Tony; Brendon (integrator) added the fault and debug screen cases (28 Oct 2026).
 * BJT2 Sound Modulating Toy — Hit Testing and Touch-to-Event Mapping
 * Author: Tony (Display/UI subsystem)
 *
 * Defines the touch regions for each screen using the menu layout
 * constants from ui_types.h. Each screen has its own static table
 * of touch_region_t entries. touch_get_event() iterates the table
 * for the active screen and returns the first matching event.
 *
 * No task of its own: tony_ui.c calls touch_get_event() inside TonyTask
 * once per tap, with the tap's screen pixel. The renderer draws its rows
 * from the same ui_types.h constants, so a tap lands on what is drawn.
 * ----------------------------------------------------------------------- */

#include "touch_region.h"
#include <stddef.h>

/* -----------------------------------------------------------------------
 * touch_hit_test
 * Half-open boundary test: x .. x+w-1 and y .. y+h-1 hit, x+w and y+h
 * do not. A zero-size region (w=0 or h=0) never hits.
 * ----------------------------------------------------------------------- */
bool touch_hit_test(uint16_t px, uint16_t py, const touch_region_t *region)
{
    if (region == NULL || region->w == 0U || region->h == 0U) {
        return false;
    }
    return (px >= region->x) &&
           (px < (uint16_t)(region->x + region->w)) &&
           (py >= region->y) &&
           (py < (uint16_t)(region->y + region->h));
}

/* -----------------------------------------------------------------------
 * Screen region tables
 * Each table entry maps a rectangular region to a ui_event_t.
 * Items are listed top-to-bottom matching the visual layout.
 * MENU_Y0 + (n * MENU_GAP) gives the y coordinate of item n.
 * ----------------------------------------------------------------------- */

/* Helper macro to build a menu row entry */
#define MENU_ROW(n, ev) \
    { MENU_X, (uint16_t)(MENU_Y0 + (n) * MENU_GAP), MENU_W, MENU_H, (ev) }

/* Home screen — six tiles, 3 rows x 2 columns */
#define HOME_CELL(n, ev) \
    { (uint16_t)HOME_CELL_X(n), (uint16_t)HOME_CELL_Y(n), HOME_CELL_W, HOME_CELL_H, (ev) }

static const touch_region_t regions_home[] = {
    HOME_CELL(0, EVENT_NAV_RECORD),
    HOME_CELL(1, EVENT_NAV_PLAY),
    HOME_CELL(2, EVENT_NAV_EFFECTS),
    HOME_CELL(3, EVENT_NAV_VOLUME),
    HOME_CELL(4, EVENT_NAV_FILE),
    HOME_CELL(5, EVENT_NAV_BATTERY),
};
static const uint8_t regions_home_count =
    (uint8_t)(sizeof(regions_home) / sizeof(regions_home[0]));

/* Dedicated HOME button — top-right corner of every screen except Home.
 * Replaces the old per-screen "Home" rows. */
static const touch_region_t region_home_btn =
    { HOME_HIT_X, HOME_HIT_Y, HOME_HIT_W, HOME_HIT_H, EVENT_GO_HOME };

/* Record screen — two items */
static const touch_region_t regions_record[] = {
    MENU_ROW(0, EVENT_RECORD_START),
    MENU_ROW(1, EVENT_RECORD_STOP),
};
static const uint8_t regions_record_count =
    (uint8_t)(sizeof(regions_record) / sizeof(regions_record[0]));

/* Play screen — one centred toggle: idle -> play, playing -> pause,
 * paused -> resume (the same event as the physical Play/Pause button).
 * No Stop: playback loops until paused or replaced by a recording. */
static const touch_region_t regions_play[] = {
    { PLAY_BTN_X - PLAY_HIT_PAD, PLAY_BTN_Y - PLAY_HIT_PAD,
      PLAY_BTN_W + 2U * PLAY_HIT_PAD, PLAY_BTN_H + 2U * PLAY_HIT_PAD, EVENT_BTN_PLAYPAUSE },
};
static const uint8_t regions_play_count =
    (uint8_t)(sizeof(regions_play) / sizeof(regions_play[0]));

/* Effects screen — six effect slots.
 * Encoder scrolls highlight (its EVENT_VOLUME_UP/DOWN, which
 * handle_effects() reads as a scroll).
 * Tapping an effect row directly selects/deselects it,
 * bypassing the scroll-then-select pattern for faster access:
 * each row has its own event, so the effect toggled is the one
 * tapped, not the one under the encoder cursor. */
static const touch_region_t regions_effects[] = {
    MENU_ROW(0, EVENT_EFFECT_PICK_1),   /* Effect 1 */
    MENU_ROW(1, EVENT_EFFECT_PICK_2),   /* Effect 2 */
    MENU_ROW(2, EVENT_EFFECT_PICK_3),   /* Effect 3 */
    MENU_ROW(3, EVENT_EFFECT_PICK_4),   /* Effect 4 */
    MENU_ROW(4, EVENT_EFFECT_PICK_5),   /* Effect 5 */
    MENU_ROW(5, EVENT_EFFECT_PICK_6),   /* Effect 6 */
};
static const uint8_t regions_effects_count =
    (uint8_t)(sizeof(regions_effects) / sizeof(regions_effects[0]));

/* Volume screen — three buttons side by side: minus, plus, mute.
 * The encoder does the same from here and from the Play screen. */
#define VOL_BTN(n, ev) \
    { (uint16_t)VOL_BTN_X(n), VOL_BTN_Y, VOL_BTN_W, VOL_BTN_H, (ev) }

static const touch_region_t regions_volume[] = {
    VOL_BTN(0, EVENT_VOLUME_DOWN),
    VOL_BTN(1, EVENT_VOLUME_UP),
    VOL_BTN(2, EVENT_MUTE_TOGGLE),
};
static const uint8_t regions_volume_count =
    (uint8_t)(sizeof(regions_volume) / sizeof(regions_volume[0]));

/* File screen — scroll and select; enc handles scroll in real firmware.
 * Row 3 is Delete (two taps 0.5 to 3 s apart, delete_confirm.c). */
static const touch_region_t regions_file[] = {
    MENU_ROW(0, EVENT_FILE_SCROLL_UP),
    MENU_ROW(1, EVENT_FILE_SCROLL_DOWN),
    MENU_ROW(2, EVENT_FILE_SELECT),
    MENU_ROW(3, EVENT_FILE_DELETE),
};
static const uint8_t regions_file_count =
    (uint8_t)(sizeof(regions_file) / sizeof(regions_file[0]));

/* Battery screen — display only; the HOME button is its only target */

/* Fault screen — no regions and no HOME button: a tap ANYWHERE dismisses
 * it (EVENT_FAULT_DISMISS), so nobody has to aim on a modal warning. */

/* Debug screen — no regions and no HOME button either: it is worked with
 * the encoder and the buttons only, so a tap anywhere does nothing. */

/* -----------------------------------------------------------------------
 * touch_get_event
 * Selects the region table for the current screen, then iterates it
 * testing each region in order. Returns the event of the first match,
 * or EVENT_NONE if no region contains (px, py).
 * ----------------------------------------------------------------------- */
ui_event_t touch_get_event(uint16_t px, uint16_t py, ui_screen_t screen)
{
    const touch_region_t *table = NULL;
    uint8_t count = 0U;

    /* Before the HOME corner check: on the fault screen that corner
     * dismisses the fault like everywhere else (no jump to Home). */
    if (screen == UI_SCREEN_FAULT) {
        return EVENT_FAULT_DISMISS;
    }

    /* Also before the HOME corner check: the debug screen draws no HOME
     * button there (short BACK leaves it), so that corner does nothing. */
    if (screen == UI_SCREEN_DEBUG) {
        return EVENT_NONE;
    }

    if (screen != UI_SCREEN_HOME && screen < UI_SCREEN_COUNT &&
        touch_hit_test(px, py, &region_home_btn)) {
        return EVENT_GO_HOME;
    }

    switch (screen) {
        case UI_SCREEN_HOME:
            table = regions_home;
            count = regions_home_count;
            break;
        case UI_SCREEN_RECORD:
            table = regions_record;
            count = regions_record_count;
            break;
        case UI_SCREEN_PLAY:
            table = regions_play;
            count = regions_play_count;
            break;
        case UI_SCREEN_EFFECTS:
            table = regions_effects;
            count = regions_effects_count;
            break;
        case UI_SCREEN_VOLUME:
            table = regions_volume;
            count = regions_volume_count;
            break;
        case UI_SCREEN_FILE:
            table = regions_file;
            count = regions_file_count;
            break;
        case UI_SCREEN_BATTERY:
            return EVENT_NONE;
        default:
            return EVENT_NONE;
    }

    for (uint8_t i = 0U; i < count; i++) {
        if (touch_hit_test(px, py, &table[i])) {
            return table[i].event;
        }
    }
    return EVENT_NONE;
}
